    EGLint v = 0;
    EGLBoolean ok = (g_egl_dpy != EGL_NO_DISPLAY && hc)
        ? eglGetConfigAttrib(g_egl_dpy, hc, (EGLint)attr, &v) : EGL_FALSE;
    if (value) *value = v;
