        if (gm_diag++ < 120 || gm_hot)
            fprintf(stderr, "[arm_jni] GetMethodID(%s %s) cls=0x%lx → 0x%x\n",
                    mn ? mn : "?", ms ? ms : "?", r1, (uint32_t)(uintptr_t)gm);
