            pfn_glGetShaderSource((GLuint)r0,(GLsizei)r1,&len,buf.data());
            if (auto *p = ctx.mem.ptr(r3)) memcpy(p,buf.data(),std::min<GuestVA>((uint32_t)len+1,r1));
