                    GuestFdWait w{ select_once, select_clear, deadline };
                    w.what = "select";
                    w.started_ms = now_ms();
                    w.last_report_ms = w.started_ms;
                    char b[64];
                    snprintf(b, sizeof b, " nfds=%d%s%s%s", nfds,
                             rp ? " r" : "", wp ? " w" : "", ep ? " e" : "");
