            *next = r0;
            it->hi = r0;
            uint64_t released = (uint64_t)old_hi - r0;
            g_mmap_prot_none_bytes =
                released < g_mmap_prot_none_bytes
                    ? g_mmap_prot_none_bytes - released : 0;
