            if (pfn_glGenTextures) pfn_glGenTextures(1, &img.tex);
            img.owns_tex = img.tex != 0;
            if (!img.w) img.w = arm_exec_fb_width();
            if (!img.h) img.h = arm_exec_fb_height();
