            uint32_t dot_va = base + 40u;  
            uint32_t emp_va = base + 44u;  
            ctx.mem.write32(dot_va, (uint32_t)'.');   /* '.' \0 \0 \0 (LE) */
            ctx.mem.write32(emp_va, 0u);               /* '\0' */
            
