        if (axis == 0 /* AXIS_X */)      v = g_ndk_input_cur.x;
        else if (axis == 1 /* AXIS_Y */) v = g_ndk_input_cur.y;
        else if (axis == 2 /* AXIS_PRESSURE */)
            v = g_ndk_input_cur.action != 1 ? 1.0f : 0.0f;
