        uint32_t buf_va = arm_malloc(ctx, (uint32_t)data.size() + 1u);
        if (!buf_va) { ret32(0); break; }
        uint8_t *dst = ctx.mem.ptr(buf_va);
        memcpy(dst, data.data(), data.size());
        dst[data.size()] = 0;
